refentry.refsect1:
  &reftitle.examples;



    Vérification de la surveillance des événements


<?php
$fp = stream_socket_client("tcp://www.qq.com:80");
Swoole\Event::add($fp, function ($fp) {
    echo fread($fp, 8192);
}, null, SWOOLE_EVENT_READ);

var_dump(Swoole\Event::isset($fp, SWOOLE_EVENT_READ)); // Affiche : true
var_dump(Swoole\Event::isset($fp, SWOOLE_EVENT_WRITE)); // Affiche : false
